  get filteredProducts(): Product[] {
    if (!this.selectedCategory) {
      return this.products;
    }
    return this.products.filter(p => p.categoryId === this.selectedCategory);
  }

  selectCategory(categoryId: string) {
    this.selectedCategory = this.selectedCategory === categoryId ? '' : categoryId;
  }

  viewProductDetails(product: Product) {
    this.router.navigate(['/b2b/marketplace', product.productId]);
  }

  addToCart(product: Product, event?: Event): void {
    if (event) {
      event.stopPropagation();
      event.preventDefault();
    }

    if (!product.productId) {
      return;
    }

    this.cartService.addToCart({
      productId: product.productId,
      name: product.productName,
      price: product.priceRange.min,
      image: product.image,
      discountValue: 0,
      discountType: 'percentage'
    } as any);
  }

  getCategoryProductCount(categoryId: string): number {
    return this.products.filter(p => p.categoryId === categoryId).length;
  }

  getSelectedCategoryName(): string {
    const category = this.categories.find(c => c.id === this.selectedCategory);
    return category ? category.name : '';
  }

  // Header navigation methods
  get cartItemCount(): number {
    return this.cartService.itemCount();
  }

  get wishlistCount(): number {
    return this.wishlistService.wishlistCount();
  }

  viewCart(): void {
    this.router.navigate(['/cart']);
  }

  navigateToUrl(url: string): void {
    this.router.navigateByUrl(url);
  }

  viewWishlist(): void {
    this.router.navigate(['/wishlist']);
  }

  viewAccount(): void {
    this.router.navigate(['/auth/signin']);
  }
